import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

   const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!billingItemCode || billingItemCode == "null" || billingItemCode == " "  ) {
    return {
      ...input,
        result: {
          rule_description: 'parameter_billingItem_code for rule not found',
          status: 'ERROR',
        }
    };
  };

  // --- 1. Asegurar estructura y obtener el id buscado ---
  const data = input?.residencial?.prices_and_method ?? [];
  const targetId = 20; 

  // --- 2. Buscar el objeto que coincida ---
  const result = data.find(p => p.price_id === targetId);


  // Asegurar contenedores
  if (!input.tsl_wo_work_order_attribute) input.tsl_wo_work_order_attribute = {};
  const workOrder = input.tsl_wo_work_order_attribute;

  if (!workOrder.billing_items) {
    workOrder.billing_items = {
      active_energy_billing_items: [],
      public_lighting_billing_items: null,
      cleaning_billing_items: null,
    };
  }

  if (!Array.isArray(workOrder.billing_items.active_energy_billing_items)) {
    workOrder.billing_items.active_energy_billing_items = [];
  }

  const items = workOrder.billing_items.active_energy_billing_items;
  // Buscar el item con billing_item_code === "consumo"
  const target = items.find(it => it?.billing_item_code === billingItemCode);

    if (target) {
    // Agregar el objeto dentro del item existente
    target.prices_and_method = result;
  } else {
    
    return {
      ...input,
      result : {
        status_code : "AFINIA-EN001-ENRE001-METODOS DE CALCULO-CONSUMO DE ENERGIA ACTIVA",
        status_description : "Error al encontrar el parameter_billingItem_code " + billingItemCode + " en el objeto billing_items de la WorkOrder",
        status_type : "ERROR"
      }
    }
  }

  return {
    ...input,
    result : {
      status_code : "AFINIA-EN001-ENRE001-METODOS DE CALCULO-CONSUMO DE ENERGIA ACTIVA",
        status_description : "Regla finalizada de forma correcta",
        status_type : "OK"
    }
  };
};

